def calculate_R(N):
    K = N + 1
    R = 0.0
    for a in range(1, N + 1):
        for b in range(1, N + 1):
            R += ((a * b) / K) % 1
    return R

# Test cases we know or suspect
N_values = [3, 7, 11]
results = {}
for N in N_values:
    R_calc = calculate_R(N)
    R_req = (N**2 - 1) / 2
    results[N] = {'R_calc': R_calc, 'R_req': R_req}

print("N=3:", results[3])
print("N=7:", results[7])
print("N=11:", results[11])

